use super::*;
#[path="../../../../📸️snapshot/🧳️state/🧪️tests/🧰️helpers/🦀️.rs"]mod helpers;
use helpers::{corpus,receive,source,grant,observe,drain,central_fragment,project_record,denied_axes};
use crate::snapshot::state::{StateZone,ModelGeometryState};
struct Zone;
impl RowBranchPath for Zone{
 type Row=StateZone;type Branch=ModelGeometryState;type Output=DirectBranchOutput<Self::Branch>;
 fn rows(o:RetainedCloneRef<'_,EnergyModelSnapshot>)->RetainedCloneRef<'_,PersistentList<StateZone>>{o.project(0,|s|&s.model.geometry.get().zones)}
 fn branch(o:RetainedCloneRef<'_,EnergyModelSnapshot>)->RetainedCloneRef<'_,ModelGeometryState>{o.project(1,|s|s.model.geometry.get())}
 fn rows_mut(b:&mut ModelGeometryState)->&mut PersistentList<StateZone>{&mut b.zones}
 fn output()->Self::Output{DirectBranchOutput::new(|b|{let mut d=EnergyModelDiff::default();d.model.geometry=Some(b);d})}
}
#[test]
fn native_ranked_row_splices_preserve_original_order_aliases_and_cancel_each_prefix(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let mut document:serde_json::Value=serde_json::from_str(include_str!("../../../../📸️snapshot/🧬️original/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();document=document["document"].take();document["model"]=corpus()["model"].clone();let mut row=document["model"]["zones"][0].clone();let rows=law["rows"].as_array().unwrap().iter().map(|id|{let mut r=row.clone();r["id"]=id.clone();r}).collect();document["model"]["zones"]=serde_json::Value::Array(rows);row["id"]=law["insert"].clone();let original=source(receive::<EnergyModelSnapshot>(&document));let authored=source(receive::<SealedShared<StateZone>>(&row));
 for case in law["cases"].as_array().unwrap(){for cut in std::iter::once(None).chain(law["cancelAt"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize))){let rank=case["rank"].as_u64().unwrap()as usize;let mut owner=if case["kind"]=="insert"{RowBranchPreparation::<Zone>::insert(rank)}else{RowBranchPreparation::<Zone>::remove(rank)};for _ in 0..cut.unwrap_or(10000){if owner.ready(){break;}let d=owner.demand(authored.borrow(),original.borrow(),4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.advance(authored.borrow(),original.borrow(),4096,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.demand(authored.borrow(),original.borrow(),4096).unwrap(),d);}let(s,h)=observe(||owner.advance(authored.borrow(),original.borrow(),4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}
 if cut.is_none(){assert!(owner.ready());let g=grant(owner.take_demand().unwrap());let(d,p)=owner.take(g).unwrap().unwrap();assert!(p.fits(g));let diff=source(d);let mut post=project_record(original.borrow());assert!(central_fragment(&diff,original.borrow(),&mut post));let rows=&post.model.geometry.get().zones;let ids:Vec<_>=(0..rows.len()).map(|i|rows.get(i).unwrap().id.0).collect();assert_eq!(serde_json::to_value(ids).unwrap(),case["after"]);assert_eq!(post.model.identity.identity(),original.borrow().get().model.identity.identity());drain(post);drain(diff);}
 owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){break;}let d=owner.close_demand(4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.close_step(denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));}let(s,h)=observe(||owner.close_step(g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));let rows=&original.borrow().get().model.geometry.get().zones;assert_eq!((rows.get(0).unwrap().id.0,rows.get(1).unwrap().id.0),(1,2));}}
 drain(authored);drain(original);
}

#[test]
fn native_creation_rank_scan_preserves_authored_sorted_order_and_distinct_refusals(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let mut document:serde_json::Value=serde_json::from_str(include_str!("../../../../📸️snapshot/🧬️original/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();document=document["document"].take();document["model"]=corpus()["model"].clone();let template=document["model"]["zones"][0].clone();document["model"]["zones"]=serde_json::Value::Array(law["rows"].as_array().unwrap().iter().map(|id|{let mut r=template.clone();r["id"]=id.clone();r}).collect());let original=source(receive::<EnergyModelSnapshot>(&document));
 for case in law["admission"].as_array().unwrap(){let key=source(case["id"].as_u64().unwrap()as u32);let mut scan=RowAdmissionScan::<StateZone>::new(case["index"].as_u64().map(|i|i as usize));for _ in 0..10000{if scan.result().is_some(){break;}let rows=Zone::rows(original.borrow());let d=scan.demand(rows,key.borrow()).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||scan.advance(rows,key.borrow(),denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));}let(s,h)=observe(||scan.advance(rows,key.borrow(),g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert_eq!(scan.result(),Some(match case["outcome"].as_str(){Some("duplicate")=>RowAdmission::Duplicate,Some("missing")=>RowAdmission::Missing,_=>RowAdmission::Rank(case["rank"].as_u64().unwrap()as usize)}));scan.begin_close();for _ in 0..100000{if scan.terminal_is_empty(){break;}let g=grant(scan.close_demand(4096).unwrap());let(s,h)=observe(||scan.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(scan.terminal_is_empty());assert_eq!(observe(||drop(scan)).1,(0,0));drain(key);}drain(original);
}
